%[text] # example for importance sampling of SRP (Ashikhmin–Shirley model)
%[text] モンテカルロ積分に使う乱数の数は `nMCint`
%[text] `それを nMC` 回行って平均と分散を計算し，plotする．（ややこしい）
clc
clear
cls

format long
%[text] ## Monte-Carlo condition & pre-allocation
nMC = 1;
srpImp = zeros(nMC, 3);
srpUni = zeros(nMC, 3);

%[text] ## object
sat = readSC('flatPlate.obj') %[output:9b1ae34f] %[output:73594590]
showSC(sat, 'Normal', 'on'); %[output:79a4e23f]
sat.Cd = 0.5;
sat.F0 = 0.5;
sat.nu = 800;
sat.nv = 150;

const = orbitConst;
d = au2km(1, const) * 10^3; % m
dAU = km2au(d ./ 10^3, const); % AU
S0 = const.S0; % Solar constant, W/m^2
c = const.c; % light speed, m/s
coeff = -S0 / c / dAU^2;
%[text] ## Ashikhmin–Shirley model
thetaI = deg2rad(20);
phiI = deg2rad(48);
sunB = [sin(thetaI)*cos(phiI), sin(thetaI)*sin(phiI), cos(thetaI)];
sunB = sunB ./ norm(sunB);

%% verification
[~, ~, srpCs] = srpASuni(sat, sunB, d, const, 10^8);
srpTrue = srpCs;

% Monte-Carlo integration condition
nMCintUni = [1e+3, 1e+4, 5e+4, 1e+5, 5e+5, 1e+6, 5e+6, 1e+7];

tic
for i = 1:length(nMCintUni)
    N = nMCintUni(i);
    for j = 1:nMC
        %[text] ## speuclar only, uniform distribution
        [~, ~, srpCs] = srpASuni(sat, sunB, d, const, N);

        srpUni(j,:) = srpCs;
    end
    stdUni(i,:) = std(srpUni, [] ,1);
    meanUni(i,:) = mean(srpUni, 1);
end
toc %[output:130ebbd1]
%[text] ## importance sampling
% Monte-Carlo integration condition
nMCintImp = nMCintUni;

tic
for i = 1:length(nMCintImp)
    N = nMCintImp(i);
    for j = 1:nMC
        [~, ~, srpCs] = srpAS(sat, sunB, d, const, N);
        srpImp(j,:) = srpCs;
    end

    stdImp(i,:) = std(srpImp, [], 1);
    meanImp(i,:) = mean(srpImp, 1);
end

toc %[output:503336b7]

%[text] ## show Figs
figure %[output:4df59e92]
tiledlayout(3,1), nexttile %[output:4df59e92]
plotStd(nMCintUni, meanUni(:,1), 3*stdUni(:,1), 'r'), hold on %[output:4df59e92]
plotStd(nMCintImp, meanImp(:,1), 3*stdImp(:,1), 'b', 'b'); %[output:4df59e92]

nexttile %[output:4df59e92]
plotStd(nMCintUni, meanUni(:,2), 3*stdUni(:,2)); hold on %[output:4df59e92]
plotStd(nMCintImp, meanImp(:,2), 3*stdImp(:,2),'b', 'b'); %[output:4df59e92]

nexttile %[output:4df59e92]
plotStd(nMCintUni, meanUni(:,3), 3*stdUni(:,3)); hold on %[output:4df59e92]
plotStd(nMCintImp, meanImp(:,3), 3*stdImp(:,3), 'b', 'b'); %[output:4df59e92]

[meanUni(end,:) %[output:group:518c64e4] %[output:554bc606]
    meanImp(end,:)] %[output:group:518c64e4] %[output:554bc606]

%% error
absErrUni = abs(srpTrue - meanUni);
absErrImp = abs(srpTrue - meanImp);
figure %[output:21bda9d9]
tiledlayout(3,1) %[output:21bda9d9]
nexttile %[output:21bda9d9]
plot(log10(nMCintUni), absErrUni(:,1), 'rx-') %[output:21bda9d9]
hold on
plot(log10(nMCintImp), absErrImp(:,1), 'bx-')
xlabel('log10(nMCint)'), ylabel('absolute error')
nexttile %[output:21bda9d9]
plot(log10(nMCintUni), absErrUni(:,2), 'gx-') %[output:21bda9d9]
hold on
plot(log10(nMCintImp), absErrImp(:,2), 'bx-')
xlabel('log10(nMCint)'), ylabel('absolute error')
nexttile %[output:21bda9d9]
plot(log10(nMCintUni), absErrUni(:,3), 'bx-') %[output:21bda9d9]
hold on
plot(log10(nMCintImp), absErrImp(:,3), 'bx-')
xlabel('log10(nMCint)'), ylabel('absolute error')

relErrUni = 100 .* abs(srpTrue - meanUni) ./ abs(srpTrue);
relErrImp = 100 .* abs(srpTrue - meanImp) ./ abs(srpTrue);
figure %[output:21bda9d9]
tiledlayout(3,1) %[output:21bda9d9]
nexttile %[output:21bda9d9]
plot(log10(nMCintUni), relErrUni(:,1), 'rx-') %[output:21bda9d9]
hold on
plot(log10(nMCintImp), relErrImp(:,1), 'bx-')
xlabel('log10(nMCint)'), ylabel('relative error, %')
nexttile %[output:21bda9d9]
plot(log10(nMCintUni), relErrUni(:,2), 'gx-') %[output:21bda9d9]
hold on
plot(log10(nMCintImp), relErrImp(:,2), 'bx-')
xlabel('log10(nMCint)'), ylabel('relative error, %')
nexttile %[output:21bda9d9]
plot(log10(nMCintUni), relErrUni(:,3), 'bx-') %[output:21bda9d9]
hold on
plot(log10(nMCintImp), relErrImp(:,3), 'bx-')
xlabel('log10(nMCint)'), ylabel('relative error, %')



